"use client";

import { useEffect, useState } from "react";
import { Plus, Search, Edit, Trash2, ExternalLink } from "lucide-react";
import Link from "next/link";

// Mock data for display until DB is connected
const MOCK_ITEMS = [
    {
        id: "1",
        title: "University Max",
        category: "Education",
        status: "published",
        updated_at: "2024-01-28",
        image: "/api/placeholder/400/320"
    },
    {
        id: "2",
        title: "Gourmet Bistro",
        category: "Food",
        status: "draft",
        updated_at: "2024-01-25",
        image: "/api/placeholder/400/320"
    },
    {
        id: "3",
        title: "Corporate Pro",
        category: "Business",
        status: "published",
        updated_at: "2024-01-20",
        image: "/api/placeholder/400/320"
    }
];

export default function PortfolioPage() {
    const [items, setItems] = useState(MOCK_ITEMS);
    const [isLoading, setIsLoading] = useState(false);

    // In a real app, fetch from Supabase here
    // useEffect(() => {
    //   const fetchItems = async () => {
    //     const { data } = await supabase.from('portfolio_items').select('*');
    //     if (data) setItems(data);
    //   };
    //   fetchItems();
    // }, []);

    return (
        <div className="space-y-6">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-gray-900">Portfolio</h1>
                    <p className="text-sm text-gray-500">Manage your projects and case studies.</p>
                </div>
                <Link
                    href="/admin/portfolio/new"
                    className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-blue-700"
                >
                    <Plus className="h-4 w-4" />
                    Add Project
                </Link>
            </div>

            <div className="flex items-center gap-3 rounded-lg border bg-white px-3 py-2">
                <Search className="h-4 w-4 text-gray-400" />
                <input
                    type="text"
                    placeholder="Search projects..."
                    className="flex-1 bg-transparent text-sm outline-none placeholder:text-gray-400"
                />
            </div>

            {isLoading ? (
                <div className="py-20 text-center text-gray-500">Loading portfolio...</div>
            ) : (
                <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                    {items.map((item) => (
                        <div key={item.id} className="group overflow-hidden rounded-xl border bg-white shadow-sm transition-all hover:shadow-md">
                            <div className="aspect-video w-full bg-gray-100 relative">
                                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                                    {/* Placeholder for image */}
                                    <span className="text-xs">Image Preview</span>
                                </div>
                            </div>
                            <div className="p-4">
                                <div className="mb-2 flex items-center justify-between">
                                    <span className={`inline-flex items-center rounded-full px-2 py-1 text-xs font-medium ${item.status === 'published'
                                            ? 'bg-green-50 text-green-700 ring-1 ring-inset ring-green-600/20'
                                            : 'bg-yellow-50 text-yellow-700 ring-1 ring-inset ring-yellow-600/20'
                                        }`}>
                                        {item.status.charAt(0).toUpperCase() + item.status.slice(1)}
                                    </span>
                                    <span className="text-xs text-gray-400">{item.category}</span>
                                </div>
                                <h3 className="line-clamp-1 font-semibold text-gray-900">{item.title}</h3>
                                <p className="mt-1 text-xs text-gray-500">Last updated: {item.updated_at}</p>

                                <div className="mt-4 flex items-center gap-2 border-t pt-4">
                                    <button className="flex-1 inline-flex items-center justify-center gap-1.5 rounded-md bg-gray-50 px-3 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-100">
                                        <Edit className="h-3 w-3" />
                                        Edit
                                    </button>
                                    <button className="inline-flex items-center justify-center rounded-md p-1.5 text-gray-400 hover:bg-red-50 hover:text-red-600">
                                        <Trash2 className="h-4 w-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}
